import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.BM_-pWjS.js";const g=JSON.parse('{"title":"What is BridgeLite","description":"","frontmatter":{},"headers":[],"relativePath":"en/introduction.md","filePath":"en/introduction.md"}'),i={name:"en/introduction.md"};function d(s,e,n,l,h,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="what-is-bridgelite" tabindex="-1">What is BridgeLite <a class="header-anchor" href="#what-is-bridgelite" aria-label="Permalink to &quot;What is BridgeLite&quot;">​</a></h1><p>BridgeLite is a <strong>lightweight image viewer</strong> for photographers who shoot RAW+JPG simultaneously.</p><p>After a shoot, your folder fills up with camera JPEGs, RAWs, and developed files all mixed together. It&#39;s easy to lose track of which ones have been developed and which haven&#39;t. Open the folder in BridgeLite and the status of all three types — along with your ratings — is clear at a glance.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>BridgeLite does just three things:</p><ul><li><strong>Browse</strong> — Scroll through large sets of photos in the thumbnail grid</li><li><strong>Evaluate</strong> — Assign 0–5 star XMP ratings at speed using keyboard shortcuts</li><li><strong>Compare</strong> — Move between camera JPEG, RAW, and developed variants as one group</li></ul><p>For developing, retouching, and exporting, keep using the tools you already know. Ratings carry over to Lightroom and Capture One as-is.</p><h2 id="grouping-feature" tabindex="-1">Grouping feature <a class="header-anchor" href="#grouping-feature" aria-label="Permalink to &quot;Grouping feature&quot;">​</a></h2><p>Developed isn&#39;t always the right answer. Sometimes the camera JPEG is simply better, and sometimes repeated edits make you lose track of where you started. BridgeLite lets you treat all three stages as one group and move between them freely.</p><h2 id="what-it-does-not-do" tabindex="-1">What it does not do <a class="header-anchor" href="#what-it-does-not-do" aria-label="Permalink to &quot;What it does not do&quot;">​</a></h2><p>BridgeLite does not develop, color grade, export, or resize images. Those tasks belong to the tools you already use, such as Lightroom or Capture One.</p><p><strong>Portable by design</strong> — BridgeLite has no proprietary catalog or database. All rating and label data is written in XMP format, making it readable by any software including Lightroom and Capture One. Your data stays intact even if you stop using BridgeLite. An internal SQLite cache is used for fast thumbnail display and filter performance, but it can be deleted at any time without affecting your photos or rating data.</p><h2 id="how-xmp-is-written" tabindex="-1">How XMP is written <a class="header-anchor" href="#how-xmp-is-written" aria-label="Permalink to &quot;How XMP is written&quot;">​</a></h2><p>Browsing, scrolling, and filtering never touch your image pixels or EXIF data. Safe to use directly from a memory card or network drive.</p><p>XMP data such as ratings is written differently depending on file type:</p><table tabindex="0"><thead><tr><th>File type</th><th>Default</th><th>Option</th></tr></thead><tbody><tr><td>JPG</td><td>Embedded in the file&#39;s XMP area</td><td>Sidecar (<code>.xmp</code>)</td></tr><tr><td>RAW</td><td>Sidecar (<code>.xmp</code>)</td><td>—</td></tr></tbody></table><p>RAW files cannot have XMP written directly by design, so the sidecar method is always used. For JPGs, XMP is embedded by default, but you can switch to sidecar mode in the settings.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>OS</td><td>macOS 14 Sonoma or later</td></tr><tr><td>Chip</td><td>Apple Silicon (M1 or later)</td></tr><tr><td>Price</td><td>Free (MIT License)</td></tr></tbody></table>',19)])])}const c=t(i,[["render",d]]);export{g as __pageData,c as default};
